    *
    * @return difference in meters
    */
   public static synchronized double computeEllipsoidToGeoidDifference(double lat, double lon)
     throws TransformException {
     // Compute the offset
     DirectPosition3D dest = new DirectPosition3D();
     mt.transform(new DirectPosition3D(lon, lat, 0), dest);
     return dest.z;
   }
 }

